    internal partial class CampTitleBinaryCreateTranslation : Fallout76MajorRecordBinaryCreateTranslation
    {
        public new static readonly CampTitleBinaryCreateTranslation Instance = new CampTitleBinaryCreateTranslation();

        public override RecordType RecordType => RecordTypes.CMPT;
        public static ParseResult FillBinaryRecordTypes(
            ICampTitleInternal item,
            MutagenFrame frame,
            PreviousParse lastParsed,
            Dictionary<RecordType, int>? recordParseCount,
            RecordType nextRecordType,
            int contentLength,
            TypedParseParams translationParams = default)
        {
            nextRecordType = translationParams.ConvertToStandard(nextRecordType);
            switch (nextRecordType.TypeInt)
            {
                case RecordTypeInts.XALG:
                {
                    frame.Position += frame.MetaData.Constants.SubConstants.HeaderLength;
                    item.XALG = ByteArrayBinaryTranslation<MutagenFrame, MutagenWriter>.Instance.Parse(reader: frame.SpawnWithLength(contentLength));
                    return (int)CampTitle_FieldIndex.XALG;
                }
                case RecordTypeInts.ANAM:
                {
                    frame.Position += frame.MetaData.Constants.SubConstants.HeaderLength;
                    item.Title = StringBinaryTranslation.Instance.Parse(
                        reader: frame.SpawnWithLength(contentLength),
                        eager: true,
                        source: StringsSource.Normal,
                        stringBinaryType: StringBinaryType.NullTerminate,
                        parseWhole: true);
                    return (int)CampTitle_FieldIndex.Title;
                }
                case RecordTypeInts.PTPR:
                {
                    frame.Position += frame.MetaData.Constants.SubConstants.HeaderLength;
                    item.IsPrefix = frame.ReadUInt8();
                    return (int)CampTitle_FieldIndex.IsPrefix;
                }
                case RecordTypeInts.PTSU:
                {
                    frame.Position += frame.MetaData.Constants.SubConstants.HeaderLength;
                    item.IsSuffix = frame.ReadUInt8();
                    return (int)CampTitle_FieldIndex.IsSuffix;
                }
                case RecordTypeInts.PTDS:
                {
                    frame.Position += frame.MetaData.Constants.SubConstants.HeaderLength;
                    item.PTDS = frame.ReadBoolean();
                    return (int)CampTitle_FieldIndex.PTDS;
                }
                case RecordTypeInts.CTDA:
                case RecordTypeInts.CITC:
                {
                    item.Conditions = 
                        Mutagen.Bethesda.Plugins.Binary.Translations.ListBinaryTranslation<Condition>.Instance.ParsePerItem(
                            reader: frame,
                            countLengthLength: 4,
                            countRecord: RecordTypes.CITC,
                            triggeringRecord: Condition_Registration.TriggerSpecs,
                            translationParams: translationParams,
                            transl: Condition.TryCreateFromBinary)
                        .CastExtendedList<Condition>();
                    return (int)CampTitle_FieldIndex.Conditions;
                }
                default:
                    return Fallout76MajorRecordBinaryCreateTranslation.FillBinaryRecordTypes(
                        item: item,
                        frame: frame,
                        lastParsed: lastParsed,
                        recordParseCount: recordParseCount,
                        nextRecordType: nextRecordType,
                        contentLength: contentLength,
                        translationParams: translationParams.WithNoConverter());
            }
        }

    }

